import heapq


def _build_quota(capacity, tie):
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        if mandatory & blocked:
            return {"error": "impossible"}
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None
        for subset in combinations(jobs, k):
            ids = tuple(sorted(job["id"] for job in subset))
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                group = job["group"]
                counts[group] = counts.get(group, 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            events = []
            for job in subset:
                events.append((job["start"], 1))
                events.append((job["end"], -1))
            active = 0
            valid = True
            for _, delta in sorted(events):
                active += delta
                if active > capacity:
                    valid = False
                    break
            if not valid:
                continue
            value = sum(job["value"] for job in subset)
            if (best_value is None or value > best_value or
                    (value == best_value and
                     ((tie == "smallest" and ids < best_ids) or
                      (tie == "largest" and ids > best_ids)))):
                best_value, best_ids = value, ids
        if best_value is None:
            return {"error": "impossible"}
        return {"selected": list(best_ids), "value": best_value}
    return solve


def _build_ledger():
    def rounded(num, den, mode):
        if mode == "half_up":
            return (num + den // 2) // den
        return num // den

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        winners = {}
        for pos, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            key = (event.get("revision", 0), pos)
            if event_id not in winners or key > winners[event_id][0]:
                winners[event_id] = (key, event)
        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in winners.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000, mode)
            tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _build_resolver():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        rows = {name: {row["version"]: row for row in packages[name]}
                for name in names}
        domains = {name: [-1] + sorted(rows[name]) for name in names}
        best = None
        best_assignment = None

        def check(assignment):
            edges = {name: [] for name in names}
            for name, bounds in data["roots"].items():
                version = assignment[name]
                if version == -1 or not bounds[0] <= version <= bounds[1]:
                    return False
            for name, version in assignment.items():
                if version == -1:
                    continue
                if version in blocked.get(name, []):
                    return False
                if name in pins and version != pins[name]:
                    return False
                row = rows[name][version]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    ov = assignment[other]
                    if ov == -1 or not dep["min"] <= ov <= dep["max"]:
                        return False
                    edges[name].append(other)
            closure = set(data["roots"])
            todo = list(closure)
            while todo:
                name = todo.pop()
                version = assignment[name]
                if version == -1:
                    return False
                for other in edges[name]:
                    if other not in closure:
                        closure.add(other)
                        todo.append(other)
            if any((assignment[name] != -1) != (name in closure) for name in names):
                return False
            state = {}
            def visit(name):
                if state.get(name) == 1:
                    return False
                if state.get(name) == 2:
                    return True
                state[name] = 1
                for other in edges[name]:
                    if not visit(other):
                        return False
                state[name] = 2
                return True
            return all(visit(name) for name in closure)

        assignment = {}
        def search(i):
            nonlocal best, best_assignment
            if i == len(names):
                score = tuple(assignment[name] for name in names)
                if (best is None or score < best) and check(assignment):
                    best = score
                    best_assignment = dict(assignment)
                return
            name = names[i]
            for version in domains[name]:
                assignment[name] = version
                search(i + 1)
            del assignment[name]

        search(0)
        if best_assignment is None:
            return {"error": "unsatisfiable"}
        return {"versions": {name: version for name, version in best_assignment.items()
                              if version != -1}}
    return solve


def _build_routes():
    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        source = data["source"]
        initial_mask = bit.get(source, 0)
        start_state = (source, initial_mask, data["coupons"])
        start = data["start"]
        dist = {start_state: start}
        queue = [(start, source, initial_mask, data["coupons"])]
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        while queue:
            time, node, mask, coupons = heapq.heappop(queue)
            state = (node, mask, coupons)
            if dist.get(state) != time:
                continue
            if node == data["target"] and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                options = [(edge["duration"], coupons)]
                if coupons:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    options.append((duration, coupons - 1))
                new_mask = mask | bit.get(edge["v"], 0)
                for duration, remaining in options:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    nxt = (edge["v"], new_mask, remaining)
                    if arrival < dist.get(nxt, float("inf")):
                        dist[nxt] = arrival
                        heapq.heappush(queue, (arrival, edge["v"], new_mask, remaining))
        return {"arrival": None}
    return solve


